const jobId = $input.item.json.params.jobId;
const body = $input.item.json.body || {};

const safe = (s) => String(s).replace(/[^a-zA-Z0-9_.:-]/g, '');
const args = [`python3 render/render.py ${safe(jobId)} --data-dir data`];
if (body.transitionType) args.push(`--transition-type ${safe(body.transitionType)}`);
if (body.transitionSeconds != null) args.push(`--transition-seconds ${Number(body.transitionSeconds)}`);
if (body.minSlideSeconds != null) args.push(`--min-slide-seconds ${Number(body.minSlideSeconds)}`);
if (body.resolution) args.push(`--resolution ${safe(body.resolution)}`);

return [{ json: { jobId, command: args.join(' ') } }];

const buf = await this.helpers.binaryToBuffer($input.item.binary.data);
const job = JSON.parse(buf.toString('utf-8'));
job.phase = 'rendering';
job.step = 'rendering';
job.updatedAt = new Date().toISOString();
const binary = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(job, null, 2)), 'job.json', 'application/json');
return [{ json: { job, jobJsonPath: `data/jobs/${job.jobId}/job.json` }, binary: { jobJson: binary } }];
